<script>
document.querySelectorAll('.procedure-toggle').forEach(toggle => { const row = toggle.closest('.procedure-row'); const sync = () => { row.querySelector('.procedure-fields').style.display = toggle.checked ? '' : 'none'; row.querySelectorAll('.procedure-fields input, .procedure-fields select, .procedure-fields textarea, input[type="hidden"]').forEach(input => input.disabled = !toggle.checked); }; toggle.addEventListener('change', sync); sync(); });
document.querySelectorAll('.status-select').forEach(select => select.addEventListener('change', () => { const row = select.closest('.procedure-row'); const quantity = row.querySelector('.quantity-input'); quantity.min = '0'; if (select.value === 'COMPLETADO' && quantity.value === '0' && quantity.max === '1') quantity.value = '1'; }));
document.querySelector('[data-session-form]')?.addEventListener('submit', event => { const button = event.submitter; if (button && button.disabled) { event.preventDefault(); return; } if (button) { button.disabled = true; button.textContent = 'Guardando…'; } });
</script>
